import com.sap.gateway.ip.core.customdev.util.Message
import com.sap.it.api.ITApiFactory
import com.sap.it.api.mapping.ValueMappingApi
import com.sap.it.api.securestore.SecureStoreService
import groovy.xml.XmlUtil

/*
 * Demo (Groovy Script 1.x): enrich a web shop order before the XSLT mapping.
 *  - value mapping: shop customer id -> S/4 sold-to party
 *  - secure store: technical user for a later HTTP call (only the user name is used here)
 *  - MPL: custom header property with the order number
 */
def Message processData(Message message) {
    def order = new XmlParser().parseText(message.getBody(String))
    def customerId = order.Customer[0].@id

    def vm = ITApiFactory.getService(ValueMappingApi, null)
    def soldTo = vm.getMappedValue('Shop', 'Customer', customerId, 'S4', 'SoldTo')
    if (soldTo == null) {
        throw new IllegalStateException("No sold-to party mapped for customer ${customerId}")
    }
    order.Customer[0].@soldTo = soldTo

    def credential = ITApiFactory.getService(SecureStoreService, null).getUserCredential('SHOP_API')
    message.setHeader('ShopUser', credential.getUsername())
    message.setProperty('SoldTo', soldTo)

    messageLogFactory.getMessageLog(message)?.addCustomHeaderProperty('OrderNumber', order.@number)

    message.setBody(XmlUtil.serialize(order))
    return message
}

import com.sap.it.api.mapping.MappingContext
import com.sap.it.api.mapping.Output

// Custom functions of a Message Mapping (run on their own; the mapping itself is not simulated).

def String getHeader(String headerName, MappingContext context) {
    return context.getHeader(headerName)
}

def String setProperty(String name, String value, MappingContext context) {
    context.setProperty(name, value)
    return value
}

// All values of a context (String[] arguments, Output): called once per context.
def void countPerContext(String[] values, Output output, MappingContext context) {
    output.addValue(values.count { !output.isSuppress(it) })
}

import com.sap.it.api.ITApiFactory
import com.sap.it.api.pd.PartnerDirectoryService
import com.sap.it.script.v2.api.Message

/*
 * Demo (Groovy Script 2.x): partner-dependent routing via the Partner Directory.
 * The sales channel from the header SalesChannel is mapped to a partner ID; its parameters give the
 * receiver URL and the sales organisation.
 */
def Message processData(Message message) {
    def pd = ITApiFactory.getService(PartnerDirectoryService, null)
    def channel = message.getHeader('SalesChannel', String)
    def partnerId = pd.getPartnerId('Shop', 'Channel', channel)
    if (partnerId == null) {
        throw new IllegalStateException("No partner maintained for sales channel ${channel}")
    }
    message.setProperty('PartnerId', partnerId)
    message.setProperty('ReceiverUrl', pd.getParameter('RECEIVER_URL', partnerId, String))
    message.setHeader('SalesOrg', pd.getParameter('SALES_ORG', partnerId, String))
    return message
}

import com.sap.it.script.v2.api.Message
import groovy.xml.XmlSlurper

/*
 * Demo (Groovy Script 2.x): validates the SalesOrderBatch from mappings/orders-to-batch.xsl
 * (input: inputs/order-batch.xml) and sets headers and exchange properties. The body stays as it is.
 */
def Message processData(Message message) {
    final String targetNamespace = 'urn:demo:integration:orders:target:v1'

    // Fine for small messages; read large ones from a Reader or stream instead of a String copy.
    String payload = message.getBody(String)
    def root = new XmlSlurper(false, true).parseText(payload)
    root.declareNamespace(t: targetNamespace)

    if (root.name() != 'SalesOrderBatch' || root.namespaceURI() != targetNamespace) {
        throw new IllegalArgumentException('Unexpected XML: SalesOrderBatch expected')
    }

    def orders = root.'t:SalesOrders'.'t:SalesOrder'
    int orderCount = orders.size()
    if (orderCount == 0) {
        throw new IllegalArgumentException('The batch contains no orders')
    }

    List<String> currencies = orders.collect { order ->
        order.'t:TotalAmount'.@currency.text()
    }.unique()
    if (currencies.size() != 1 || !currencies[0]) {
        throw new IllegalArgumentException('All orders must have the same currency')
    }

    BigDecimal batchTotal = orders.inject(BigDecimal.ZERO) { BigDecimal sum, order ->
        String amount = order.'t:TotalAmount'.text()
        sum.add(new BigDecimal(amount))
    }
    String formattedTotal = batchTotal.setScale(2).toPlainString()
    String currency = currencies[0]

    // Headers, e.g. for a receiver adapter.
    message.setHeader('Content-Type', 'application/xml; charset=UTF-8')
    message.setHeader('X-Order-Count', orderCount.toString())
    message.setHeader('X-Order-Total', formattedTotal)
    message.setHeader('X-Currency', currency)

    // Exchange properties, e.g. for a router, content modifier or monitoring.
    message.setProperty('orderCount', orderCount)
    message.setProperty('orderTotal', formattedTotal)
    message.setProperty('orderCurrency', currency)

    return message
}

import com.sap.it.api.mapping.MappingContext

// A Message Mapping function that tells null from an empty string (regression: a test case's null argument).
def String classify(String value, MappingContext context) {
    return value == null ? 'NULL' : value.isEmpty() ? 'EMPTY' : 'VALUE'
}

import com.sap.gateway.ip.core.customdev.util.Message

/*
 * Demo (Groovy Script 1.x): read a text attachment that came with the message (e.g. from a
 * mail or AS2 sender) and pass its first line on as a header.
 */
def Message processData(Message message) {
    def note = message.getAttachments()['delivery-note.txt']
    if (note == null) {
        throw new IllegalStateException('Attachment delivery-note.txt is missing')
    }
    def firstLine = note.getContent().text.readLines().find { it.trim() } ?: ''
    message.setHeader('DeliveryNote', firstLine.trim())
    message.setProperty('AttachmentCount', message.getAttachments().size())
    return message
}

